      var paymentCard=document.createElement('section');paymentCard.className='card';var payments=(data.payments||[]).map(function(payment){var telegram=payment.telegram_status?'<span class="sub">Telegram: '+h(label(payment.telegram_status))+(payment.telegram_error?' · '+h(payment.telegram_error):'')+'</span>':'';return '<div class="item"><strong>'+h(label(payment.method))+' · '+pill(payment.status)+'</strong><span class="sub">'+money(payment.received_amount_minor==null?payment.expected_amount_minor:payment.received_amount_minor,payment.currency)+' · '+h(payment.provider||'без провайдера')+(payment.external_reference?' · № '+h(payment.external_reference):'')+'</span>'+telegram+(state.user.role==='owner'&&payment.status==='pending_verification'?'<div class="actions"><button class="btn primary" data-confirm-payment="'+h(payment.id)+'">Подтвердить здесь</button><button class="btn" data-reject-payment="'+h(payment.id)+'">Отклонить</button></div>':'')+'</div>'}).join('')||'<p class="hint">Платежей на проверке пока нет.</p>';var paymentForm=['owner','finance'].includes(state.user.role)?'<form id="paymentForm"><div class="form-row"><label class="field"><span>Способ</span><select name="method"><option value="bank_transfer">Перевод</option><option value="payment_provider">Платёжный сервис</option><option value="cash">Наличные</option><option value="other">Другое</option></select></label><label class="field"><span>Сумма перевода</span><input name="expectedAmount" inputmode="decimal" placeholder="например 1500 или 1500,50" required></label><label class="field"><span>Валюта</span><input name="currency" value="'+h(order.sale_currency)+'" readonly></label></div><div class="form-row"><label class="field"><span>Банк или сервис</span><input name="provider" placeholder="например СБП"></label><label class="field"><span>Номер операции</span><input name="externalReference" placeholder="если есть"></label><label class="field"><span>Примечание</span><input name="note"></label></div><button class="btn primary">Записать и подготовить Telegram</button></form><p class="notice">После записи откройте «Автоматизацию» и отправьте запрос администратору. Не вводите номер карты, CVV или данные криптокошелька.</p>':'';paymentCard.innerHTML='<h3>Проверка оплаты</h3>'+payments+paymentForm;stacks[1].prepend(paymentCard);
      var cargoCard=document.createElement('section');cargoCard.className='card';var shipments=(data.shipments||[]).map(function(shipment){return '<div class="item"><strong>'+h(shipment.cargo_name)+' · '+pill(shipment.status)+'</strong><span class="sub">'+shipment.pieces+' мест · '+h(shipment.tracking_code||'трек не указан')+'</span>'+(state.user.role==='owner'?'<div class="actions"><select data-shipment-status="'+h(shipment.id)+'">'+statusOptions(['pending_confirmation','confirmed','partially_shipped','shipped','delivered','not_collected','returning','returned','issue','cancelled'],shipment.status)+'</select><button class="btn" data-save-shipment="'+h(shipment.id)+'">Подтвердить статус</button></div>':'')+'</div>'}).join('')||'<p class="hint">Отправлений карго пока нет.</p>';var cargoForm=['owner','manager'].includes(state.user.role)?'<form id="shipmentForm"><div class="form-row"><label class="field"><span>Карго</span><input name="cargoName" required></label><label class="field"><span>Трек-номер</span><input name="trackingCode"></label><label class="field"><span>Количество мест</span><input name="pieces" type="number" min="1" value="1" required></label></div><button class="btn">Передать отправление на подтверждение</button></form><p class="hint">Карго сообщает статус; окончательное подтверждение в системе делает владелец.</p>':'';cargoCard.innerHTML='<h3>Карго и отправления</h3>'+shipments+cargoForm;stacks[0].appendChild(cargoCard);
      var buyerForm=document.getElementById('buyerTypeForm');if(buyerForm)buyerForm.onsubmit=async function(event){event.preventDefault();try{await api('/api/admin/orders/'+encodeURIComponent(orderId),{method:'PATCH',body:formObject(event.currentTarget)});toast('Тип покупателя сохранён');await openOrder(orderId)}catch(error){toast(error.message)}};
